import React from "react";

const AboutPage = () => (
  <div className="max-w-3xl mx-auto py-12 px-4">
    <h1 className="text-3xl font-bold mb-4">Tentang Kami</h1>
    <p className="mb-4">Selamat datang di Online Shop kami! Kami menyediakan berbagai produk berkualitas dengan harga terjangkau. Kepuasan pelanggan adalah prioritas utama kami.</p>
    <p className="mb-4">Didirikan pada tahun 2025, kami berkomitmen untuk memberikan pelayanan terbaik dan pengalaman belanja online yang mudah, aman, dan menyenangkan.</p>
    <p>Hubungi kami untuk kerjasama atau pertanyaan lebih lanjut. Terima kasih telah berbelanja di toko kami!</p>
  </div>
);

export default AboutPage;
